import sys,time
INF=100000000
MATE=100000
VALUE={'p':100,'n':320,'b':330,'r':500,'q':900,'k':20000}
PROM={1:'n',2:'b',3:'r',4:'q'}

class Position:
    def __init__(self,board,side,rights,ep,half,full):
        self.b=board
        self.side=side
        self.rights=rights
        self.ep=ep
        self.half=half
        self.full=full
    @classmethod
    def fen(cls,text):
        a=text.split()
        board=['.']*64
        for i,row in enumerate(a[0].split('/')):
            sq=(7-i)*8
            for ch in row:
                if ch.isdigit():
                    sq+=int(ch)
                else:
                    board[sq]=ch
                    sq+=1
        rights=0
        for i,ch in enumerate('KQkq'):
            if ch in a[2]:
                rights|=1<<i
        ep=-1
        if a[3]!='-':
            ep=ord(a[3][0])-97+8*(int(a[3][1])-1)
        return cls(board,0 if a[1]=='w' else 1,rights,ep,int(a[4]),int(a[5]))
    @classmethod
    def start(cls):
        return cls.fen('rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1')

def king_square(p,side):
    target='K' if side==0 else 'k'
    for i,ch in enumerate(p.b):
        if ch==target:
            return i
    return -1

def attacked(p,sq,by):
    if sq<0 or sq>=64:
        return False
    b=p.b
    r,f=divmod(sq,8)
    pr=r-1 if by==0 else r+1
    pawn='P' if by==0 else 'p'
    if 0<=pr<8:
        for ff in (f-1,f+1):
            if 0<=ff<8 and b[pr*8+ff]==pawn:
                return True
    knight='N' if by==0 else 'n'
    for dr,df in ((2,1),(2,-1),(-2,1),(-2,-1),(1,2),(1,-2),(-1,2),(-1,-2)):
        x,y=r+dr,f+df
        if 0<=x<8 and 0<=y<8 and b[x*8+y]==knight:
            return True
    royal='K' if by==0 else 'k'
    for dr in (-1,0,1):
        for df in (-1,0,1):
            if dr or df:
                x,y=r+dr,f+df
                if 0<=x<8 and 0<=y<8 and b[x*8+y]==royal:
                    return True
    for dr,df,chars in ((1,0,'rq'),(-1,0,'rq'),(0,1,'rq'),(0,-1,'rq'),(1,1,'bq'),(1,-1,'bq'),(-1,1,'bq'),(-1,-1,'bq')):
        x,y=r+dr,f+df
        while 0<=x<8 and 0<=y<8:
            ch=b[x*8+y]
            if ch!='.':
                if ch.isupper()==(by==0) and ch.lower() in chars:
                    return True
                break
            x+=dr
            y+=df
    return False

def castle_safe(p,src,dst):
    b=p.b[:]
    pc=b[src]
    b[src]='.'
    b[dst]=pc
    q=Position(b,p.side,p.rights,p.ep,p.half,p.full)
    return not attacked(q,dst,p.side^1)

def pseudo(p,captures=False):
    b=p.b
    white=p.side==0
    out=[]
    def add(a,z,pr=0,fl=0,cap=False):
        if not captures or cap or pr:
            out.append((a,z,pr,fl))
    for s,pc in enumerate(b):
        if pc=='.' or pc.isupper()!=white:
            continue
        r,f=divmod(s,8)
        typ=pc.lower()
        if typ=='p':
            d=8 if white else -8
            z=s+d
            last=7 if white else 0
            if 0<=z<64 and b[z]=='.':
                if z//8==last:
                    for pr in (4,3,2,1):
                        add(s,z,pr)
                else:
                    add(s,z)
                    if not captures and r==(1 if white else 6) and b[s+2*d]=='.':
                        add(s,s+2*d,0,4)
            for df in (-1,1):
                if not 0<=f+df<8:
                    continue
                z=s+d+df
                if not 0<=z<64:
                    continue
                target=b[z]
                enemy=target!='.' and target.isupper()!=white and target.lower()!='k'
                if enemy:
                    if z//8==last:
                        for pr in (4,3,2,1):
                            add(s,z,pr,0,True)
                    else:
                        add(s,z,0,0,True)
                elif z==p.ep:
                    cs=z-8 if white else z+8
                    if 0<=cs<64 and b[cs]==('p' if white else 'P'):
                        add(s,z,0,2,True)
        elif typ=='n':
            for dr,df in ((2,1),(2,-1),(-2,1),(-2,-1),(1,2),(1,-2),(-1,2),(-1,-2)):
                x,y=r+dr,f+df
                if 0<=x<8 and 0<=y<8:
                    z=x*8+y
                    if b[z]=='.':
                        add(s,z)
                    elif b[z].isupper()!=white and b[z].lower()!='k':
                        add(s,z,0,0,True)
        elif typ in 'brq':
            dirs=[]
            if typ in 'bq':
                dirs += [(1,1),(1,-1),(-1,1),(-1,-1)]
            if typ in 'rq':
                dirs += [(1,0),(-1,0),(0,1),(0,-1)]
            for dr,df in dirs:
                x,y=r+dr,f+df
                while 0<=x<8 and 0<=y<8:
                    z=x*8+y
                    if b[z]=='.':
                        add(s,z)
                    else:
                        if b[z].isupper()!=white and b[z].lower()!='k':
                            add(s,z,0,0,True)
                        break
                    x+=dr
                    y+=df
        else:
            for dr in (-1,0,1):
                for df in (-1,0,1):
                    if dr or df:
                        x,y=r+dr,f+df
                        if 0<=x<8 and 0<=y<8:
                            z=x*8+y
                            if b[z]=='.':
                                add(s,z)
                            elif b[z].isupper()!=white and b[z].lower()!='k':
                                add(s,z,0,0,True)
            if not captures and s==(4 if white else 60) and not attacked(p,s,p.side^1):
                if white and p.rights&1 and b[5]==b[6]=='.' and b[7]=='R' and castle_safe(p,4,5) and castle_safe(p,4,6):
                    add(4,6,0,1)
                if white and p.rights&2 and b[1]==b[2]==b[3]=='.' and b[0]=='R' and castle_safe(p,4,3) and castle_safe(p,4,2):
                    add(4,2,0,1)
                if not white and p.rights&4 and b[61]==b[62]=='.' and b[63]=='r' and castle_safe(p,60,61) and castle_safe(p,60,62):
                    add(60,62,0,1)
                if not white and p.rights&8 and b[57]==b[58]==b[59]=='.' and b[56]=='r' and castle_safe(p,60,59) and castle_safe(p,60,58):
                    add(60,58,0,1)
    return out

def make_move(p,m):
    a,z,pr,fl=m
    b=p.b[:]
    pc=b[a]
    captured=b[z]
    b[a]='.'
    if fl&2:
        cs=z-8 if pc.isupper() else z+8
        captured=b[cs]
        b[cs]='.'
    b[z]=pc
    if fl&1:
        if z==6:
            b[5]=b[7]; b[7]='.'
        elif z==2:
            b[3]=b[0]; b[0]='.'
        elif z==62:
            b[61]=b[63]; b[63]='.'
        elif z==58:
            b[59]=b[56]; b[56]='.'
    if pr:
        b[z]=('NBRQ'[pr-1] if pc.isupper() else 'nbrq'[pr-1])
    rights=p.rights
    if pc=='K': rights&=12
    if pc=='k': rights&=3
    if a==0 or z==0: rights&=~2
    if a==7 or z==7: rights&=~1
    if a==56 or z==56: rights&=~8
    if a==63 or z==63: rights&=~4
    ep=(a+z)//2 if pc.lower()=='p' and abs(z-a)==16 else -1
    half=0 if pc.lower()=='p' or captured!='.' else p.half+1
    full=p.full+(1 if p.side==1 else 0)
    return Position(b,p.side^1,rights,ep,half,full)

def legal_moves(p,captures=False):
    ks=king_square(p,p.side)
    if ks<0:
        return []
    out=[]
    side=p.side
    for m in pseudo(p,captures):
        q=make_move(p,m)
        if not attacked(q,king_square(q,side),side^1):
            out.append(m)
    return out

def uci_move(m):
    a,z,pr,fl=m
    s='abcdefgh'[a&7]+str(a//8+1)+'abcdefgh'[z&7]+str(z//8+1)
    return s+(PROM[pr] if pr else '')

class Engine:
    def __init__(self):
        self.pos=Position.start()
        self.tt={}
        self.history={}
        self.killers={}
        self.nodes=0
        self.deadline=0.0
    def evaluate(self,p):
        score=0
        phase=0
        wp=[0]*8
        bp=[0]*8
        bishops_w=0
        bishops_b=0
        for ch in p.b:
            if ch!='.' and ch.lower() not in 'pk':
                phase+=VALUE[ch.lower()]
        for s,ch in enumerate(p.b):
            if ch=='.':
                continue
            typ=ch.lower()
            sign=1 if ch.isupper() else -1
            score+=sign*VALUE[typ]
            r,f=divmod(s,8)
            rr=r if sign==1 else 7-r
            center=7-abs(2*f-7)-abs(2*rr-7)
            if typ=='p':
                (wp if sign==1 else bp)[f]+=1
                score+=sign*(rr*9+center*2)
                passed=True
                ranks=range(r+1,8) if sign==1 else range(r-1,-1,-1)
                enemy='p' if sign==1 else 'P'
                for r2 in ranks:
                    for f2 in (f-1,f,f+1):
                        if 0<=f2<8 and p.b[r2*8+f2]==enemy:
                            passed=False
                if passed:
                    score+=sign*(16+rr*8)
            elif typ=='n':
                score+=sign*center*11
            elif typ=='b':
                score+=sign*center*5
                if sign==1: bishops_w+=1
                else: bishops_b+=1
            elif typ=='r':
                score+=sign*(rr*3+(6 if f in (3,4) else 0))
                files=wp if sign==1 else bp
                if files[f]==0:
                    score+=sign*12
            elif typ=='q':
                score+=sign*center*2
            else:
                if phase>2600:
                    score-=sign*center*3
                else:
                    score+=sign*center*11
        if bishops_w>=2: score+=30
        if bishops_b>=2: score-=30
        for n in wp: score-=max(0,n-1)*10
        for n in bp: score+=max(0,n-1)*10
        for f,n in enumerate(wp):
            if n and (f==0 or wp[f-1]==0) and (f==7 or wp[f+1]==0): score-=10*n
        for f,n in enumerate(bp):
            if n and (f==0 or bp[f-1]==0) and (f==7 or bp[f+1]==0): score+=10*n
        return score if p.side==0 else -score
    def check_time(self):
        self.nodes+=1
        if (self.nodes&15)==0 and time.perf_counter()>=self.deadline:
            raise TimeoutError
    def move_score(self,p,m,ttmove,ply):
        a,z,pr,fl=m
        score=10000000 if m==ttmove else 0
        cap=p.b[z]
        if fl&2: cap='p'
        if cap!='.': score+=1000000+VALUE[cap.lower()]*10-VALUE[p.b[a].lower()]
        if pr: score+=800000+pr*10000
        if self.killers.get(ply)==m: score+=500000
        score+=self.history.get((p.side,a,z),0)
        if fl&1: score+=100
        return score
    def qsearch(self,p,alpha,beta,ply):
        self.check_time()
        incheck=attacked(p,king_square(p,p.side),p.side^1)
        if incheck:
            moves=legal_moves(p)
            if not moves:
                return -MATE+ply
        elif ply>=10:
            moves=legal_moves(p)
            return 0 if not moves else self.evaluate(p)
        else:
            stand=self.evaluate(p)
            if stand>=beta: return stand
            if stand>alpha: alpha=stand
            moves=legal_moves(p,True)
            if not moves:
                return 0 if not legal_moves(p) else alpha
        moves.sort(key=lambda x:self.move_score(p,x,None,ply),reverse=True)
        for m in moves:
            value=-self.qsearch(make_move(p,m),-beta,-alpha,ply+1)
            if value>=beta: return value
            if value>alpha: alpha=value
        return alpha
    def search(self,p,depth,alpha,beta,ply):
        self.check_time()
        if depth<=0:
            return self.qsearch(p,alpha,beta,ply)
        key=(tuple(p.b),p.side,p.rights,p.ep,p.half)
        original_alpha=alpha
        original_beta=beta
        entry=self.tt.get(key)
        ttmove=None
        if entry and entry[0]>=depth:
            ttmove=entry[3]
            value,flag=entry[1],entry[2]
            if flag==0: return value
            if flag==1: alpha=max(alpha,value)
            else: beta=min(beta,value)
            if alpha>=beta: return value
        elif entry:
            ttmove=entry[3]
        moves=legal_moves(p)
        if not moves:
            return -MATE+ply if attacked(p,king_square(p,p.side),p.side^1) else 0
        moves.sort(key=lambda x:self.move_score(p,x,ttmove,ply),reverse=True)
        best=-INF
        bestmove=moves[0]
        for m in moves:
            value=-self.search(make_move(p,m),depth-1,-beta,-alpha,ply+1)
            if value>best:
                best=value
                bestmove=m
            if value>alpha: alpha=value
            if alpha>=beta:
                a,z,pr,fl=m
                if p.b[a].lower()!='p' and p.b[z]=='.' and not pr:
                    self.killers[ply]=m
                    keyh=(p.side,a,z)
                    self.history[keyh]=min(10000,self.history.get(keyh,0)+depth*depth)
                break
        flag=0 if best>original_alpha and best<original_beta else (2 if best<=original_alpha else 1)
        self.tt[key]=(depth,best,flag,bestmove)
        if len(self.tt)>160000:
            self.tt.clear()
        return best
    def root(self,p,moves,depth):
        alpha=-INF
        best=-INF
        bestmove=moves[0]
        ordered=moves[:]
        ordered.sort(key=lambda x:self.move_score(p,x,None,0),reverse=True)
        for m in ordered:
            self.check_time()
            value=-self.search(make_move(p,m),depth-1,-INF,-alpha,1)
            if value>best:
                best=value
                bestmove=m
            if value>alpha:
                alpha=value
        return best,bestmove
    def think(self,millis):
        moves=legal_moves(self.pos)
        if not moves:
            return '0000'
        best=moves[0]
        if millis<=3:
            return uci_move(best)
        self.nodes=0
        self.deadline=time.perf_counter()+max(0.0005,millis/1000.0*0.82)
        for depth in range(1,64):
            try:
                value,m=self.root(self.pos,moves,depth)
            except TimeoutError:
                break
            best=m
            if abs(value)>=MATE-1000:
                break
        return uci_move(best)
    def set_position(self,a):
        if len(a)>=2 and a[1]=='startpos':
            p=Position.start()
            i=2
        elif len(a)>=8 and a[1]=='fen':
            p=Position.fen(' '.join(a[2:8]))
            i=8
        else:
            return
        if i<len(a) and a[i]=='moves':
            for text in a[i+1:]:
                found=None
                for m in legal_moves(p):
                    if uci_move(m)==text:
                        found=m
                        break
                if found is not None:
                    p=make_move(p,found)
        self.pos=p

def main():
    engine=Engine()
    for line in sys.stdin:
        a=line.strip().split()
        if not a:
            continue
        if a[0]=='uci':
            print('id name PythonScratch')
            print('id author Codex')
            print('uciok')
            sys.stdout.flush()
        elif a[0]=='isready':
            print('readyok')
            sys.stdout.flush()
        elif a[0]=='ucinewgame':
            engine.tt.clear()
            engine.history.clear()
            engine.killers.clear()
        elif a[0]=='position':
            engine.set_position(a)
        elif a[0]=='go':
            millis=1000
            if 'movetime' in a:
                try:
                    millis=max(1,int(a[a.index('movetime')+1]))
                except (ValueError,IndexError):
                    millis=1
            print('bestmove '+engine.think(millis))
            sys.stdout.flush()
        elif a[0]=='quit':
            break

if __name__=='__main__':
    main()
